def _blocks(grid, background):
    """Return contiguous bands of rows containing non-background pattern cells."""
    result = []
    start = None
    for r, row in enumerate(grid):
        active = any(v != background for v in row)
        if active and start is None:
            start = r
        elif not active and start is not None:
            result.append((start, r))
            start = None
    if start is not None:
        result.append((start, len(grid)))
    return result


def transform(grid):
    """Complete a repeated horizontal pattern, marking the copied cells with 1.

    A repeated band may be horizontally translated.  The denser occurrence is
    the source; cells present in that source but absent in its aligned copy are
    marked 1.  Simple rows with a contrasting terminal run are handled as the
    one-row tail form of the same completion rule.
    """
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    blocks = _blocks(grid, background)

    # Compare repeated bands of equal height under bounded horizontal shifts.
    # Select the strongest near-subset alignment and copy only missing cells.
    best = None
    for i, (a0, a1) in enumerate(blocks):
        ah = a1 - a0
        if ah == 0:
            continue
        for b0, b1 in blocks[i + 1:]:
            if b1 - b0 != ah:
                continue
            # Positive d places the second occurrence d columns to the right.
            for d in range(-min(8, w // 3), min(8, w // 3) + 1):
                src_fg = dst_fg = conflicts = overlap = 0
                missing = []
                extra = []
                for k in range(ah):
                    for c in range(w):
                        t = c + d
                        if not (0 <= t < w):
                            continue
                        sfg = grid[a0 + k][c] != background
                        tfg = grid[b0 + k][t] != background
                        overlap += 1
                        src_fg += sfg
                        dst_fg += tfg
                        if sfg and not tfg:
                            missing.append((b0 + k, t))
                        elif tfg and not sfg:
                            extra.append((a0 + k, c))
                        if sfg != tfg:
                            conflicts += 1
                if overlap < ah * w * 0.65 or src_fg < 4 or dst_fg < 4:
                    continue
                # A copy can have a few missing pixels, but shouldn't be a
                # substantially different pattern or have gaps in both directions.
                if conflicts > max(5, int(overlap * 0.14)):
                    continue
                if missing and extra:
                    continue
                source_is_first = src_fg >= dst_fg
                if not missing and not extra:
                    continue
                fill = missing if source_is_first else extra
                # score: favor high overlap and few one-sided differences.
                score = (conflicts, -overlap, -max(src_fg, dst_fg), abs(d))
                if best is None or score < best[0]:
                    best = (score, fill)
    if best is not None:
        for r, c in best[1]:
            if out[r][c] == background:
                out[r][c] = 1

    # The same completion appears as a single row with a solid, contrasting
    # terminal run after an initial foreground run.
    for r, row in enumerate(grid):
        if row[0] == background:
            continue
        lead = row[0]
        c = 1
        while c < w and row[c] == lead:
            c += 1
        if c < w and all(v == background for v in row[c:]):
            for j in range(c, w):
                out[r][j] = 1
    return out


